// "Create for X": electric sheets, PLC program and operator panel generated by HYDRA from a hydraulic / pneumatic
// sheet's tag list, with the same machine kit the sample machine uses (machines/kit.ts). Runs on a project draft, so
// it becomes one plan → Apply → one undo step. The fluid sheet only gets solenoid tags where a valve has none.
import { mkNode, type Project } from '../store';
import { geomOf, isConn, isAsm, hasSolenoid } from '../designer/geom';
import { netsOf, type Sheet, type Comp } from '../designer/model';
import { electrics, frame, finder, OPERATOR, LAMPS, tidyPanel, go, type In, type Out, type Motor } from '../machines/kit';
import * as P from '../machines/prog';
import { signals } from '../plc/signals';
import { compile } from '../plc/compile';
import { autoBuild } from '../plc/panel/model';
import { fail } from './core';

type Cyl = { tag: string; ext?: { sol: string; on: boolean }; ret?: { sol: string; on: boolean }; lp: string; lm: string };
const solSides = (g: any) => ({ a: (g.valve?.ops?.left || []).some((o: any) => ['solenoid', 'proportional', 'servo'].includes(o.type)), b: (g.valve?.ops?.right || []).some((o: any) => ['solenoid', 'proportional', 'servo'].includes(o.type)) });

/** tags, solenoids and which solenoid moves which cylinder, read from the fluid sheet */
function analyse(d: Project, sh: Sheet, notes: string[]) {
  const cn = String(sh.circuitNo || 1); const plain = sh.components.filter(c => !isConn(c.ref) && !isAsm(c.ref));
  const used = new Set<string>(); Object.values(d.circuits).forEach((c: any) => (c.components || []).forEach((x: any) => { if (x.tag) used.add(x.tag); ['ya', 'yb'].forEach(k => { if (x.values?.[k]) used.add(String(x.values[k])); }); }));
  const fresh = (letter: string) => { let n = 1; while (used.has(`${cn}${letter}${n}`)) n++; const t = `${cn}${letter}${n}`; used.add(t); return t; };
  // solenoid tags: keep the user's, add the missing ones (Values › Solenoid a / b tag)
  const valves = plain.filter(c => hasSolenoid(geomOf(c.ref).valve));
  valves.forEach(v => { const s = solSides(geomOf(v.ref)); v.values = v.values || {}; (['a', 'b'] as const).forEach(k => { if (s[k] && !v.values!['y' + k]) { v.values!['y' + k] = fresh('Y'); notes.push(`${v.tag}: solenoid ${k} tagged ${v.values!['y' + k]}`); } }); });
  // which valve port reaches each cylinder port (through flow / check valves)
  const nets = netsOf(sh); const netOf = (c: string, p: string) => nets.find(n => n.ports.some(q => q.c === c && q.p === p));
  const byId = new Map(plain.map(c => [c.id, c]));
  function valvePort(cid: string, port: string, seen = new Set<string>()): { v: Comp; p: string } | null {
    const n = netOf(cid, port); if (!n) return null;
    for (const q of n.ports) { if (q.c === cid) continue; const c = byId.get(q.c); if (!c) continue; if (valves.includes(c)) return { v: c, p: geomOf(c.ref).ports.find(x => x.key === q.p)?.name || q.p };
      const g = geomOf(c.ref); if (g.ports.length === 2 && !seen.has(c.id) && ['flow', 'check', 'shutoff', 'pressure', 'filter'].includes(g.cls)) { seen.add(c.id); const other = g.ports.find(x => x.key !== q.p)!; const r = valvePort(c.id, other.key, seen); if (r) return r; } }
    return null;
  }
  const cyls: Cyl[] = plain.filter(c => geomOf(c.ref).cls === 'cylinder').map((c, i) => {
    const cap = valvePort(c.id, 'A'), rod = valvePort(c.id, 'B'); const r = cap || rod; const lp = `${cn}B${2 * i + 1}`, lm = `${cn}B${2 * i + 2}`; used.add(lp); used.add(lm);
    if (!r) { notes.push(`${c.tag}: no solenoid valve found on its lines — moved by hand only`); return { tag: c.tag, lp, lm }; }
    const v = r.v, s = solSides(geomOf(v.ref)); const capOnA = cap ? cap.p === 'A' : rod!.p !== 'A';
    const sa = v.values!.ya, sb = v.values!.yb; // solenoid a pressurises port A (ISO 1219 box a)
    const extSide = capOnA ? 'a' : 'b', retSide = capOnA ? 'b' : 'a';
    const sol = (k: 'a' | 'b') => (k === 'a' ? (s.a ? sa : null) : (s.b ? sb : null));
    const ext = sol(extSide) ? { sol: sol(extSide)!, on: true } : sol(retSide) ? { sol: sol(retSide)!, on: false } : undefined;
    const ret = sol(retSide) ? { sol: sol(retSide)!, on: true } : sol(extSide) ? { sol: sol(extSide)!, on: false } : undefined;
    return { tag: c.tag, ext, ret, lp, lm };
  });
  const motors: Motor[] = plain.filter(c => geomOf(c.ref).cls === 'drive').map((c, i) => ({ tag: c.tag, kw: Math.round(((c.values?.p as number) || 5500) / 100) / 10, contactor: `${cn}K${i + 1}` }));
  const psw = plain.filter(c => /pswitch|pressure switch/i.test(c.ref + ' ' + geomOf(c.ref).name));
  return { cn, valves, cyls, motors, psw };
}

const parentOf = (d: Project, sheetId: string) => Object.values(d.nodes).find(n => n.children.includes(sheetId))?.id || d.rootId;
function addSheet(d: Project, parent: string, name: string, body: any, description = '') {
  const taken = new Set(Object.values(d.nodes).map(n => n.name)); let nm = name, k = 2; while (taken.has(nm)) nm = `${name} (${k++})`;
  const n = mkNode('sheet', nm, parent, { sheetType: 'electric', size: 'A3', description }); d.nodes[n.id] = n; d.nodes[parent].children.push(n.id);
  d.circuits[n.id] = { id: n.id, type: 'electric', name: nm, connections: [], ...body, size: 'A3' }; return nm;
}
const plcIn = (d: Project, tag: string) => signals(d).sigs.some((s: any) => s.src === 'plc' && s.dir === 'in' && s.tag === tag);

export type CreateOpts = { sequence?: string[]; name?: string };
export function createFor(d: Project, sh: Sheet, domain: 'electric' | 'logic' | 'controller', o: CreateOpts = {}) {
  const notes: string[] = []; const out: any = { domain, sheet: sh.name };
  const A = analyse(d, sh, notes);
  if (!A.cyls.length && !A.motors.length && !A.valves.length) fail(`${sh.name} has no cylinders, motors or solenoid valves to control`);
  const op = A.cn === '0' ? '9' : '0'; // operator station tags (0S1 …) stay apart from the circuit's tags
  // ---- electric ----
  const needElec = domain === 'electric' || !plcIn(d, `${op}S2`);
  if (domain === 'electric' && plcIn(d, `${op}S2`)) fail(`Electric sheets for the PLC I/O already exist (${op}S2 is wired) — delete them first to create new ones`);
  if (needElec) {
    const ins: In[] = [...OPERATOR(op), ...A.cyls.flatMap(c => [{ tag: c.lp, dev: 'limit', func: `${c.tag} extended`, watch: c.tag, end: '+' } as In, { tag: c.lm, dev: 'limit', func: `${c.tag} retracted`, watch: c.tag, end: '-' } as In]),
      ...A.psw.map(c => ({ tag: c.tag, dev: 'psw', func: `${c.tag} pressure reached` } as In))];
    const sols = [...new Set(A.valves.flatMap(v => [v.values!.ya, v.values!.yb].filter(Boolean) as string[]))];
    const outs: Out[] = [...sols.map(s => ({ tag: s, dev: 'sol', func: `${s} solenoid` } as Out)), ...A.motors.map(m => ({ tag: m.contactor, dev: 'coil', func: `${m.tag} motor contactor` } as Out)), ...LAMPS(op)];
    const parent = parentOf(d, sh.id);
    out.sheets = electrics(sh.name, ins, outs, A.motors).map(s => addSheet(d, parent, `${sh.name} · ${s.name}`, s.draw({}), s.description));
    out.io = { inputs: ins.length, outputs: outs.length };
  }
  if (domain === 'electric') return { ...out, notes };
  // ---- PLC program ----
  const S = finder(d); const X = (t: string) => P.inp(S.X(t)), Y = (t: string) => S.Y(t), Q = S.Q;
  const letters = new Map(A.cyls.map((c, i) => [String.fromCharCode(65 + i), c]));
  const pick = (s: string) => { const m = /^(.+?)\s*([+-])$/.exec(String(s).trim()); if (!m) fail(`Sequence step "${s}" — write e.g. 1A1+ or A-`); const c = A.cyls.find(x => x.tag === m![1]) || letters.get(m![1].toUpperCase()); if (!c) fail(`Sequence step "${s}": no cylinder ${m![1]}`, [`Cylinders: ${A.cyls.map((c, i) => `${c.tag} (${String.fromCharCode(65 + i)})`).join(', ')}`]); return { c: c!, end: m![2] as '+' | '-' }; };
  const seqIn = o.sequence?.length ? o.sequence : [...A.cyls.map(c => c.tag + '+'), ...A.cyls.slice().reverse().map(c => c.tag + '-')];
  const steps = seqIn.map(pick);
  const ext = new Set<string>(); const auto: P.St[] = [['S0', 'Idle', [P.msg('AUTO — press START')], go()]];
  steps.forEach((s, i) => {
    if (s.end === '+') ext.add(s.c.tag); else ext.delete(s.c.tag);
    const dir = s.end === '+' ? s.c.ext : s.c.ret; const acts: any[] = [];
    if (dir?.on) acts.push(P.act(Y(dir.sol)));
    // single-solenoid valves: hold the solenoid while a cylinder must stay out (or in)
    A.cyls.forEach(c => { if (c === s.c) return; const hold = ext.has(c.tag) ? c.ext : c.ret; if (hold?.on && hold.sol && (c.ext?.sol === c.ret?.sol)) acts.push(P.act(Y(hold.sol))); });
    auto.push([`S${i + 1}`, `${s.c.tag} ${s.end === '+' ? 'extend' : 'retract'}`, acts, X(s.end === '+' ? s.c.lp : s.c.lm)]);
  });
  auto.push([`S${steps.length + 1}`, 'Cycle end', [], P.T, 'S0']);
  const retractAll = A.cyls.filter(c => c.ret?.on).map(c => P.act(Y(c.ret!.sol)));
  const homeDone = A.cyls.length ? P.and(...A.cyls.map(c => X(c.lm))) : P.T;
  const name = o.name || `${sh.name} control`;
  const existing = domain === 'controller' ? Object.values(d.programs).filter((x: any) => x.sheet === sh.id).pop() as any : null;
  if (existing) { out.program = existing.name; return panelFor(d, existing, out, notes); }
  const spec = frame({ name, comment: `Generated from ${sh.name}: AUTO ${seqIn.join(' ')} · SETUP homing · MANUAL jog`, vars: [],
    start: S.X(`${op}S2`), stop: S.X(`${op}S3`), estop: S.X(`${op}S1`), pumps: A.motors.flatMap(m => S.pump(m.tag, m.contactor)),
    lamps: { run: Q(`${op}H1`), fault: Q(`${op}H2`), homed: Q(`${op}H3`) },
    auto, homing: [['H1', 'Retract all', retractAll, homeDone]], manual: [], alarms: [] });
  let progs = Object.values(d.nodes).find(n => n.type === 'programs');
  if (!progs) { progs = mkNode('programs', 'Programs', d.rootId); d.nodes[progs.id] = progs; d.nodes[d.rootId].children.push(progs.id); }
  const pn = mkNode('program', name, progs.id, { language: 'Blocks' }); d.nodes[pn.id] = pn; d.nodes[progs.id].children.push(pn.id);
  const anyActive = Object.values(d.programs).some((x: any) => x.active);
  const pr: any = { id: pn.id, name, language: 'Blocks', ws: spec.ws, vars: spec.vars, scanMs: 10, active: !anyActive, estop: spec.estop, estopNc: spec.estopNc, stall: 15, comment: spec.comment || '', sheet: sh.id };
  d.programs[pn.id] = pr; out.program = name; out.sequence = seqIn;
  if (domain === 'controller') return panelFor(d, pr, out, notes);
  return { ...out, notes };
}

// ---- operator panel: auto-built from the project, as the sample machine's ----
function panelFor(d: Project, pr: any, out: any, notes: string[]) {
  {
    const T = signals(d); const c = compile(pr, T);
    const { panel, newVars } = autoBuild(d, pr, T, { seqs: c.seqs.map((q: any) => ({ name: q.name, steps: q.steps.map((s: any) => s.id) })), counters: c.counters });
    tidyPanel(panel);
    // auto-build adds a jog pair per cylinder: keep only the ones the program reads (as the sample machine does)
    const wsTxt = JSON.stringify(pr.ws); const unused = new Set(newVars.filter((v: any) => !wsTxt.includes(JSON.stringify(v.id))).map((v: any) => v.id));
    panel.widgets = panel.widgets.filter((w: any) => ![w.p.act, w.p.act2].some((a: any) => typeof a === 'string' && unused.has(a.replace(/^var:/, ''))));
    pr.vars = [...pr.vars, ...newVars.filter((v: any) => !unused.has(v.id))]; pr.panel = panel; out.panel = { widgets: panel.widgets.length };
  }
  return { ...out, notes };
}
